+/// @file simple_gravity_test.cpp
+/// @author Assistant
+/// @brief 简单的重力补偿测试
+/// @version 0.1
+/// @date 2024-01-01
+/// @copyright Copyright (c) 2024
+
+#include "../include/imu_processor.h"
+#include <iostream>
